// [WSCoop] A removed map marker takes its tooltip with it.
if (MapElementWidget.RegisteredElement.UniqueId.ToString().StartsWith(WSMapMarkers::ElementPrefix))
    MenuAnchor_Tooltip.OnUnhovered();

// [WSCoop] Map markers: R / gamepad Reset marks the centre of the view (or removes your marker there).
UFUNCTION()
private void WSOnMarkerAction()
{
    const FGeometry& Geometry = GetCachedGeometry();
    const FVector2D Center = Geometry.LocalToAbsolute(Geometry.GetLocalSize() * 0.5);
    WSMapMarkers::OnMapActionPressed(ScreenToWorld(Center), 3.0 / Math::Max(CurrentZoom, 0.1));
}
